WITH recent_subscriptions AS (SELECT *, TRIM(plan) clean_plan FROM subscriptions WHERE plan IN ('premium', 'basic') AND plan = 'basic'), Agg AS (SELECT DATE_TRUNC('MONTH', start_date) start_month, CASE WHEN monthly_fee >= 247 THEN 'high' WHEN monthly_fee >= 52 THEN 'mid' ELSE 'low' END monthly_fee_bucket, SUM(CASE WHEN plan = 'standard' THEN 1 ELSE 0 END) standard_count, COUNT(DISTINCT monthly_fee) unique_customers FROM recent_subscriptions GROUP BY DATE_TRUNC('MONTH', start_date), CASE WHEN monthly_fee >= 247 THEN 'high' WHEN monthly_fee >= 52 THEN 'mid' ELSE 'low' END) SELECT start_month, monthly_fee_bucket, standard_count, unique_customers FROM Agg WHERE standard_count > 64 ORDER BY monthly_fee_bucket, start_month
